Question 3  
-- ===================================================== 
-- COMPANY DATABASE - COMPLETE DDL 
-- ===================================================== 


-- 1. EMPLOYEE 
-- SUPERSSN is a self-referencing foreign key 

CREATE TABLE EMPLOYEE ( 
    FNAME VARCHAR(20) NOT NULL, 
    MINIT CHAR(1), 
    LNAME VARCHAR(20) NOT NULL, 
    SSN CHAR(9) PRIMARY KEY, 
    BDATE DATE, 
    ADDRESS VARCHAR(100), 
    SEX CHAR(1), 
    SALARY DECIMAL(10,2), 
    SUPERSSN CHAR(9), 
    DNO INT, 

    FOREIGN KEY (SUPERSSN) 
        REFERENCES EMPLOYEE(SSN) 
); 


-- 2. DEPARTMENT 
-- MGRSSN references EMPLOYEE 

CREATE TABLE DEPARTMENT ( 
    DNAME VARCHAR(30) NOT NULL, 
    DNUMBER INT PRIMARY KEY, 
    MGRSSN CHAR(9), 
    MGRSTARTDATE DATE, 

    FOREIGN KEY (MGRSSN) 
        REFERENCES EMPLOYEE(SSN) 
); 


-- 3. Add EMPLOYEE.DNO foreign key 
-- DNO references DEPARTMENT.DNUMBER 

ALTER TABLE EMPLOYEE 

ADD CONSTRAINT fk_employee_department 
FOREIGN KEY (DNO) 
REFERENCES DEPARTMENT(DNUMBER); 


-- 4. DEPT_LOCATIONS 
-- Composite primary key: (DNUMBER, DLOCATION) 

CREATE TABLE DEPT_LOCATIONS ( 
    DNUMBER INT, 
    DLOCATION VARCHAR(30), 

    PRIMARY KEY (DNUMBER, DLOCATION), 

    FOREIGN KEY (DNUMBER) 
        REFERENCES DEPARTMENT(DNUMBER) 
); 


-- 5. PROJECT 
-- PNUMBER is primary key 
-- DNUM references DEPARTMENT 

CREATE TABLE PROJECT ( 
    PNAME VARCHAR(30), 
    PNUMBER INT PRIMARY KEY, 
    PLOCATION VARCHAR(30), 
    DNUM INT, 

    FOREIGN KEY (DNUM) 
        REFERENCES DEPARTMENT(DNUMBER) 
); 


-- 6. WORKS_ON 
-- Composite primary key: (ESSN, PNO) 
-- Both foreign keys use CASCADE 

CREATE TABLE WORKS_ON ( 
    ESSN CHAR(9), 
    PNO INT, 
    HOURS DECIMAL(5,2), 

    PRIMARY KEY (ESSN, PNO), 


    FOREIGN KEY (ESSN) 
        REFERENCES EMPLOYEE(SSN) 
        ON DELETE CASCADE 
        ON UPDATE CASCADE, 

    FOREIGN KEY (PNO) 
        REFERENCES PROJECT(PNUMBER) 
        ON DELETE CASCADE 
        ON UPDATE CASCADE 
); 


-- 7. DEPENDENT 
-- Composite primary key: (ESSN, DEPENDENT_NAME) 

CREATE TABLE DEPENDENT ( 
    ESSN CHAR(9), 
    DEPENDENT_NAME VARCHAR(30), 
    SEX CHAR(1), 
    BDATE DATE, 
    RELATIONSHIP VARCHAR(30), 

    PRIMARY KEY (ESSN, DEPENDENT_NAME), 

    FOREIGN KEY (ESSN) 
        REFERENCES EMPLOYEE(SSN) 
); 


-- ===================================================== 
-- PART (d) 
-- Add CHECK constraint on SALARY 
-- Set default value of 1 for DNO 
-- ===================================================== 

ALTER TABLE EMPLOYEE 
ADD CONSTRAINT employee_salary_chk 
CHECK (SALARY > 0); 


ALTER TABLE EMPLOYEE 
ALTER COLUMN DNO SET DEFAULT 1; 



